<script setup lang="ts">import { computed, ref } from 'vue'; import { useAppStore } from '@/stores/app'; import TaskRow from '@/components/task/TaskRow.vue'; import type { Project } from '@/types'; const props=defineProps<{project:Project}>(); const app=useAppStore(); const filter=ref(''); const rows=computed(()=>app.tasks.filter(t=>t.projectId===props.project.id&&t.title.toLowerCase().includes(filter.value.toLowerCase())))</script>
<template><section class="panel"><div class="toolbar"><input v-model="filter" placeholder="Filter tasks"/><select><option>All statuses</option><option>Open</option><option>Completed</option></select><select><option>Sort by updated</option><option>Sort by priority</option></select></div><div class="task-list"><TaskRow v-for="t in rows" :key="t.id" :task="t"/></div></section></template>
